ook-cover.webp","medium":"/default-book-cover.webp","large":"/default-book-cover.webp"},"status":"unread","shelf_id":"5e324e7e-59c5-5cb9-b4d4-01c429d8f067","shelf_name":"Biblioteca empotrada · balda inferior"}],"shelves":[{"id":"shelf-1","title":"Predeterminada","isDefault":true,"book_count":0},{"id":"546be8c7-3338-5310-b149-dcebd0c5868b","title":"Biblioteca empotrada · balda superior","isDefault":false,"book_count":30},{"id":"5e324e7e-59c5-5cb9-b4d4-01c429d8f067","title":"Biblioteca empotrada · balda inferior","isDefault":false,"book_count":40},{"id":"14644d15-b7bc-5ed6-8de1-ab24eb0d9b06","title":"Estante de cristal · foto 4","isDefault":false,"book_count":21},{"id":"c12dabd6-f489-52fd-80ce-d17a751b47e4","title":"Estante de cristal · foto 5","isDefault":false,"book_count":20}]}$biblib_data$::jsonb;
BEGIN
  v_user_id := COALESCE(v_user_id, v_session_user);
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Indica el UUID de tu usuario de Supabase Auth en v_user_id antes de importar';
  END IF;
  IF v_session_user IS NOT NULL AND v_session_user <> v_user_id THEN
    RAISE EXCEPTION 'El usuario indicado no coincide con la sesión autenticada';
  END IF;
  PERFORM set_config('request.jwt.claim.sub', v_user_id::text, true);
  PERFORM set_config('request.jwt.claims', jsonb_build_object('sub', v_user_id, 'role', 'authenticated')::text, true);

  INSERT INTO biblib.shelves (user_id, title, is_default)
  SELECT v_user_id, shelf->>'title', false
  FROM jsonb_array_elements(v_data->'shelves') AS shelf
  WHERE NOT (shelf->>'isDefault')::boolean
  ON CONFLICT (user_id, title) DO NOTHING;

  INSERT INTO biblib.books (user_id, isbn, title, subtitle, authors, publishers, number_of_pages, publish_date, cover_small, cover_medium, cover_large, status, shelf_id)
  SELECT v_user_id, book->>'isbn', book->>'title', book->>'subtitle',
    book->'authors', book->'publishers', (book->>'number_of_pages')::integer, book->>'publish_date',
    book->'cover'->>'small', book->'cover'->>'medium', book->'cover'->>'large', book->>'status', target.id
  FROM jsonb_array_elements(v_data->'books') AS book
  JOIN biblib.shelves AS target ON target.user_id = v_user_id AND target.title = book->>'shelf_name'
  ON CONFLICT (user_id, isbn) DO NOTHING;
  GET DIAGNOSTICS v_inserted = ROW_COUNT;
  RAISE NOTICE 'Libros añadidos: %. Duplicados omitidos: %.', v_inserted, jsonb_array_length(v_data->'books') - v_inserted;
END;
$biblib_import$;
COMMIT;
